context_title:
Ezt html css js be teljes kódot kijavítva vissza küldöd. minden egyes karaktert leírsz, nem rövidítesz. minden hibát kijavítasz. egy fájl marad. ne írj semmi mást csak a teljes kódot es kommentek nem lehetnek benne! soha semmi egyszerusitett mock placeholder dummy szimulalt fake szart nem engedelyezek es teljes fájl roviditetlen production ready kód  egy kód mezőbe írjad a teljes kódot es legyen 100% osan hiba mentes! 


import React, { useState, useEffect } from 'react';
import { 
  X, Search, FileText, Settings, Terminal, Play, 
  Zap, Database, User, Plus, Folder, 
  Upload, Download, Menu, ChevronRight, 
  MoreHorizontal, Code, Globe, Cpu, Lock
} from 'lucide-react';

const PaneHeader = ({ title, icon: Icon, iconColor, onClose }) => (
  <div className="h-[52px] flex items-center justify-between px-2 border-b border-[#2b2d31] bg-[#1c1c1e] shrink-0">
    <div className="flex items-center gap-2 min-w-[40px]"></div>
    <div className="flex items-center gap-2 font-medium text-[#e3e3e3]">
      {Icon && <Icon size={16} className={iconColor} />}
      <span>{title}</span>
    </div>
    <div className="flex items-center gap-2 min-w-[40px] justify-end">
      <button className="p-2 rounded-md text-[#9d9d9d] hover:text-white hover:bg-[#ffffff10]" onClick={onClose}>
        <X size={20} />
      </button>
    </div>
  </div>
);

const FileTreeItem = ({ name, type = 'file', depth = 0, active }) => {
  const Icon = type === 'folder' ? Folder : FileText;
  const color = type === 'folder' ? 'text-blue-400' : 'text-gray-400';
  return (
    <div 
      className={`flex items-center justify-between px-3 py-2 hover:bg-[#2b2d31] cursor-pointer group ${active ? 'bg-[#2b2d31]' : ''}`}
      style={{ paddingLeft: `${depth * 16 + 12}px` }}
    >
      <div className="flex items-center gap-2 overflow-hidden">
        <Icon size={16} className={color} />
        <span className="text-[#e3e3e3] text-sm truncate">{name}</span>
      </div>
      <button className="opacity-0 group-hover:opacity-100 text-gray-500 hover:text-white">
        <MoreHorizontal size={14} />
      </button>
    </div>
  );
};

const EditorView = () => (
  <div className="flex flex-col h-full bg-[#1c1c1e] text-sm font-mono overflow-hidden">
    <PaneHeader title="main.py" icon={FileText} iconColor="text-blue-400" />
    <div className="flex-1 overflow-auto p-4 flex">
      <div className="flex flex-col text-[#505050] text-right pr-4 select-none min-w-[24px]">
        {Array.from({length: 12}).map((_, i) => <div key={i} className="leading-6">{i+1}</div>)}
      </div>
      <div className="flex-1 whitespace-pre leading-6 text-[#d4d4d4]">
        <div><span className="text-[#c586c0]">import</span> os</div>
        <div><span className="text-[#c586c0]">import</span> flask</div>
        <div className="h-6"></div>
        <div><span className="text-[#9cdcfe]">app</span> = flask.Flask(__name__)</div>
        <div className="h-6"></div>
        <div><span className="text-[#dcdcaa]">@app.route</span>(<span className="text-[#ce9178]">'/'</span>)</div>
        <div><span className="text-[#c586c0]">def</span> <span className="text-[#dcdcaa]">index</span>():</div>
        <div>  <span className="text-[#c586c0]">return</span> <span className="text-[#ce9178]">"Hello from Replit!"</span></div>
        <div className="h-6"></div>
        <div><span className="text-[#c586c0]">if</span> __name__ == <span className="text-[#ce9178]">"__main__"</span>:</div>
        <div>  app.run(host=<span className="text-[#ce9178]">'0.0.0.0'</span>, port=81)</div>
      </div>
    </div>
  </div>
);

const AgentView = () => (
  <div className="flex flex-col h-full bg-[#1c1c1e]">
    <PaneHeader title="Agent" icon={Zap} iconColor="text-purple-400" />
    <div className="flex-1 flex flex-col items-center justify-center p-6 text-center gap-6 overflow-y-auto">
      <div className="w-16 h-16 bg-gradient-to-br from-purple-500 to-blue-500 rounded-2xl flex items-center justify-center shadow-lg shadow-purple-900/20">
        <Zap size={32} className="text-white" />
      </div>
      <div className="space-y-2">
        <h2 className="text-xl font-semibold text-white">Új csevegés az Agenttel</h2>
        <p className="text-[#9d9d9d] text-sm max-w-xs mx-auto">Az Agent képes módosítani a kódot, átnézni a munkáját és automatikusan javítani a hibákat.</p>
      </div>
      <div className="flex flex-wrap gap-2 justify-center max-w-sm">
        {['Hibák keresése', 'Fizetési rendszer hozzáadása', 'AI asszisztens csatlakoztatása', 'SMS küldés funkció', 'Adatbázis integrálása', 'Bejelentkezés létrehozása'].map((label) => (
          <button key={label} className="bg-[#2b2d31] hover:bg-[#3f4148] text-[#e3e3e3] px-3 py-2 rounded-lg text-sm border border-[#3f4148] transition-colors">{label}</button>
        ))}
      </div>
    </div>
    <div className="p-4 border-t border-[#2b2d31]">
        <div className="bg-[#2b2d31] rounded-xl p-3 flex items-center gap-3 border border-[#3f4148]">
             <div className="flex-1 text-sm text-[#9d9d9d]">Készíts, tesztelj, ismételj...</div>
             <div className="flex gap-2">
                 <button className="text-[#9d9d9d] hover:text-white"><Code size={16} /></button>
                 <div className="bg-[#0079F2] p-1.5 rounded-lg text-white cursor-pointer"><ChevronRight size={16} /></div>
             </div>
        </div>
    </div>
  </div>
);

const ShellView = () => (
  <div className="flex flex-col h-full bg-[#1c1c1e]">
    <PaneHeader title="Shell" icon={Terminal} iconColor="text-gray-400" />
    <div className="flex-1 bg-[#1c1c1e] p-2 font-mono text-sm overflow-auto">
      <div className="text-gray-400">~/workspace $ <span className="text-white">python3 main.py</span></div>
      <div className="text-white opacity-80 mt-1"> * Serving Flask app 'main'</div>
      <div className="text-white opacity-80"> * Debug mode: off</div>
      <div className="text-red-400 opacity-90">WARNING: This is a development server. Do not use it in a production deployment.</div>
      <div className="text-white opacity-80"> * Running on </div>
      <div className="mt-1 w-2 h-4 bg-gray-500 animate-pulse"></div>
    </div>
  </div>
);

const ConsoleView = () => (
  <div className="flex flex-col h-full bg-[#1c1c1e]">
    <PaneHeader title="Console" icon={Terminal} iconColor="text-yellow-500" />
    <div className="flex-1 p-4 flex flex-col items-center justify-center text-center">
      <div className="text-[#e3e3e3] text-sm mb-4">A kód futtatásakor itt jelennek meg az eredmények</div>
      <button className="bg-[#2b2d31] hover:bg-[#3f4148] text-green-500 px-4 py-2 rounded-lg text-sm border border-[#3f4148] flex items-center gap-2">
        <Play size={12} fill="currentColor" />
        Futtatás
      </button>
    </div>
  </div>
);

const DeveloperView = () => (
  <div className="flex flex-col h-full bg-[#1c1c1e]">
    <PaneHeader title="Developer" icon={Settings} iconColor="text-blue-500" />
    <div className="p-4 space-y-6 overflow-y-auto">
      <h3 className="text-white font-medium text-xl mb-1">Developer Tools</h3>
      <div className="space-y-2">
        <button className="w-full flex items-center justify-between bg-[#2b2d31] p-3 rounded-xl border border-[#3f4148] hover:bg-[#3f4148]">
          <div className="flex items-center gap-3">
            <Globe size={18} className="text-[#e3e3e3]" />
            <div className="text-left">
              <div className="text-white text-sm font-medium">Networking</div>
              <div className="text-[#9d9d9d] text-xs">Portok konfigurálása</div>
            </div>
          </div>
          <ChevronRight size={16} className="text-[#9d9d9d]" />
        </button>
        <button className="w-full flex items-center justify-between bg-[#2b2d31] p-3 rounded-xl border border-[#3f4148] hover:bg-[#3f4148]">
          <div className="flex items-center gap-3">
            <Cpu size={18} className="text-[#e3e3e3]" />
            <div className="text-left">
              <div className="text-white text-sm font-medium">Resources</div>
              <div className="text-[#9d9d9d] text-xs">CPU és Memória figyelése</div>
            </div>
          </div>
          <ChevronRight size={16} className="text-[#9d9d9d]" />
        </button>
      </div>
    </div>
  </div>
);

export default function App() {
  const [activeView, setActiveView] = useState('editor');
  const [showFiles, setShowFiles] = useState(true);
  const views = [
    { id: 'shell', component: <ShellView />, label: 'Shell' },
    { id: 'console', component: <ConsoleView />, label: 'Console' },
    { id: 'editor', component: <EditorView />, label: 'Editor' },
    { id: 'agent', component: <AgentView />, label: 'Agent' },
    { id: 'developer', component: <DeveloperView />, label: 'Dev' }
  ];
  const activeIndex = views.findIndex(v => v.id === activeView);

  return (
    <div className="flex flex-col h-screen w-full bg-black text-[#e3e3e3] overflow-hidden font-sans select-none relative">
      <style>{`
        :root {
          --neon-green: #39FF14;
          --deep-blue: #0044FF;
          --accent-green-bright: #adff2f;
          --button-bg: rgba(255, 255, 255, 0.02);
        }
        body {
          background-color: #000000;
          margin: 0;
          overflow: hidden;
        }
        .glow-bg {
          position: absolute;
          width: 600px;
          height: 600px;
          border-radius: 50%;
          filter: blur(150px);
          z-index: 0;
          opacity: 0.12;
          pointer-events: none;
        }
        .glow-green {
          background: var(--neon-green);
          top: 10%;
          left: -10%;
        }
        .glow-blue {
          background: var(--deep-blue);
          bottom: 10%;
          right: -10%;
        }
        @keyframes slideIn {
          from { transform: translateY(100%); }
          to { transform: translateY(0); }
        }
        .animate-slide-up {
          animation: slideIn 0.2s ease-out forwards;
        }
      `}</style>

      <div className="glow-bg glow-green"></div>
      <div className="glow-bg glow-blue"></div>

      <div className="h-[52px] bg-[#1c1c1e]/80 backdrop-blur-md border-b border-[#2b2d31] flex items-center justify-between px-3 z-50">
        <div className="flex items-center justify-center w-8 h-8 rounded hover:bg-[#2b2d31]">
          <svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor"><path d="M12 1.25a2.75 2.75 0 0 1 1.583.5l.192.149.004.004 6.995 5.996a2.752 2.752 0 0 1 .976 2.1v9A2.752 2.752 0 0 1 19 21.75h-3.98l-.02.002-.02-.002H9.02l-.02.002-.02-.002H5A2.75 2.75 0 0 1 2.25 19v-9a2.75 2.75 0 0 1 .975-2.1l6.996-5.996.004-.004A2.75 2.75 0 0 1 12 1.249Z"></path></svg>
        </div>
        <span className="font-medium text-[#e3e3e3]">Python (Production)</span>
        <div className="w-8 h-8 rounded hover:bg-[#2b2d31] flex items-center justify-center">
          <MoreHorizontal size={20} />
        </div>
      </div>

      <div className="h-0.5 bg-[#2b2d31] flex w-full z-50">
         {views.map((view, i) => (
             <div key={view.id} className={`flex-1 transition-all duration-300 ${i === activeIndex ? 'bg-[#39FF14] shadow-[0_0_8px_#39FF14]' : 'bg-transparent'}`}/>
         ))}
      </div>

      <div className="flex-1 relative overflow-hidden">
        <div 
            className="absolute inset-0 flex transition-transform duration-300 ease-out h-full"
            style={{ transform: `translateX(-${activeIndex * 100}%)` }}
        >
            {views.map((view) => (
                <div key={view.id} className="min-w-full h-full relative bg-[#1c1c1e]/40 backdrop-blur-[2px]">
                    {view.component}
                </div>
            ))}
        </div>
        <div className="absolute top-0 bottom-20 left-0 w-8 z-10" onClick={() => setActiveView(views[Math.max(0, activeIndex - 1)].id)} />
        <div className="absolute top-0 bottom-20 right-0 w-8 z-10" onClick={() => setActiveView(views[Math.min(views.length - 1, activeIndex + 1)].id)} />
      </div>

      <div className={`absolute bottom-[80px] left-0 right-0 px-4 pb-4 flex items-center justify-between transition-all duration-300 z-30 pointer-events-none ${showFiles ? 'opacity-0 scale-95' : 'opacity-100 scale-100'}`}>
        <div className="flex gap-2 w-full justify-between pointer-events-auto">
            <button className="flex items-center justify-center gap-2 bg-[#1c1c1e]/90 backdrop-blur-xl p-3 rounded-2xl border border-[#2b2d31] shadow-2xl flex-1 active:scale-95 transition-transform h-12">
                <Lock size={18} className="text-[#39FF14]" />
                <span className="text-xs font-bold text-[#e3e3e3]">SECRETS</span>
            </button>
            <button className="flex items-center justify-center gap-2 bg-[#1c1c1e]/90 backdrop-blur-xl p-3 rounded-2xl border border-[#2b2d31] shadow-2xl flex-1 active:scale-95 transition-transform h-12">
                <Database size={18} className="text-[#0044FF]" />
                <span className="text-xs font-bold text-[#e3e3e3]">DB</span>
            </button>
            <button className="flex items-center justify-center gap-2 bg-[#1c1c1e]/90 backdrop-blur-xl p-3 rounded-2xl border border-[#2b2d31] shadow-2xl w-12 active:scale-95 transition-transform h-12">
                <Plus size={24} className="text-white" />
            </button>
        </div>
      </div>

      {showFiles && (
        <div className="absolute inset-0 z-40 flex flex-col justify-end">
            <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setShowFiles(false)} />
            <div className="relative bg-[#1c1c1e] rounded-t-3xl shadow-2xl border-t border-[#3f4148] max-h-[75vh] flex flex-col w-full animate-slide-up pb-[80px]">
                <div className="w-12 h-1.5 bg-[#3f4148] rounded-full mx-auto mt-3 mb-2" />
                <div className="flex items-center justify-between px-6 py-4 border-b border-[#2b2d31]">
                    <h2 className="text-xl font-bold text-[#e3e3e3]">Projekt fájlok</h2>
                    <button onClick={() => setShowFiles(false)} className="p-1 hover:bg-[#2b2d31] rounded-full"><X size={24} className="text-[#9d9d9d]" /></button>
                </div>
                <div className="overflow-y-auto p-4 flex-1">
                    <FileTreeItem name="main.py" type="file" depth={0} active />
                    <FileTreeItem name="templates" type="folder" depth={0} />
                    <FileTreeItem name="static" type="folder" depth={0} />
                    <FileTreeItem name="replit.nix" type="file" depth={0} />
                    <FileTreeItem name="pyproject.toml" type="file" depth={0} />
                </div>
                <div className="p-4 border-t border-[#2b2d31] grid grid-cols-2 gap-3 bg-[#1c1c1e]">
                    <button className="flex items-center justify-center gap-2 bg-[#2b2d31] text-[#e3e3e3] border border-[#3f4148] rounded-xl py-3 font-medium"><Plus size={18}/> Új fájl</button>
                    <button className="flex items-center justify-center gap-2 bg-[#2b2d31] text-[#e3e3e3] border border-[#3f4148] rounded-xl py-3 font-medium"><Upload size={18}/> Feltöltés</button>
                </div>
            </div>
        </div>
      )}

      <div className="h-[80px] bg-[#1c1c1e]/90 backdrop-blur-lg border-t border-[#2b2d31] flex items-center justify-between px-6 z-50 absolute bottom-0 w-full">
        <button 
            className={`p-3 rounded-2xl transition-all ${showFiles ? 'text-[#39FF14] bg-[#39FF14]/10 shadow-[inset_0_0_10px_rgba(57,255,20,0.2)]' : 'text-[#9d9d9d] hover:text-white'}`}
            onClick={() => setShowFiles(!showFiles)}
        >
            <Menu size={28} />
        </button>
        <button className="flex-1 mx-4 h-12 bg-[#2b2d31] rounded-2xl flex items-center px-4 gap-3 text-[#9d9d9d] border border-[#3f4148] hover:bg-[#3f4148] transition-all group">
            <Search size={18} className="group-hover:text-[#39FF14]" />
            <span className="text-sm font-medium">Keresés a fájlokban...</span>
        </button>
        <div className="w-12 h-12 rounded-2xl bg-gradient-to-br from-[#39FF14] to-[#0044FF] p-[2px] active:scale-95 transition-transform">
            <div className="w-full h-full bg-[#1c1c1e] rounded-[14px] flex items-center justify-center">
                <Play size={20} className="text-[#39FF14] ml-1" fill="currentColor" />
            </div>
        </div>
      </div>
    </div>
  );
}

