<script>
const views = ['shell', 'console', 'editor', 'agent', 'developer'];
let activeViewIndex = 2;
const viewSlider = document.getElementById('viewSlider');
const menuButton = document.getElementById('menuButton');
const filesOverlay = document.getElementById('filesOverlay');
const filesBackdrop = document.getElementById('filesBackdrop');
const filesClose = document.getElementById('filesClose');
const floatingButtons = document.getElementById('floatingButtons');
const progressSegments = document.querySelectorAll('.progress-segment');
function updateView() {
viewSlider.style.transform = 'translateX(-' + (activeViewIndex * 100) + '%)';
progressSegments.forEach(function(segment, index) {
if (index === activeViewIndex) {
segment.classList.add('active');
} else {
segment.classList.remove('active');
}
});
}
function showFiles() {
filesOverlay.classList.remove('hidden');
floatingButtons.classList.remove('visible');
floatingButtons.classList.add('hidden');
menuButton.classList.add('active');
menuButton.classList.remove('inactive');
}
function hideFiles() {
filesOverlay.classList.add('hidden');
floatingButtons.classList.remove('hidden');
floatingButtons.classList.add('visible');
menuButton.classList.remove('active');
menuButton.classList.add('inactive');
}
menuButton.addEventListener('click', function() {
if (filesOverlay.classList.contains('hidden')) {
showFiles();
} else {
hideFiles();
}
});
filesBackdrop.addEventListener('click', hideFiles);
filesClose.addEventListener('click', hideFiles);
let touchStartX = 0;
let touchEndX = 0;
viewSlider.addEventListener('touchstart', function(e) {
touchStartX = e.changedTouches[0].screenX;
}, false);
viewSlider.addEventListener('touchend', function(e) {
touchEndX = e.changedTouches[0].screenX;
handleSwipe();
}, false);
function handleSwipe() {
if (touchEndX < touchStartX - 50) {
if (activeViewIndex < views.length - 1) {
activeViewIndex++;
updateView();
}
}
if (touchEndX > touchStartX + 50) {
if (activeViewIndex > 0) {
activeViewIndex--;
updateView();
}
}
}
updateView();
menuButton.classList.add('active');
</script>
